              {deleteTarget?.type === 'key' ? '确定要删除全部 API Key 吗？删除后将无法使用 AI 功能。'
                : deleteTarget?.type === 'key_single' ? '确定要删除这个 API Key 吗？'
                : '确定要删除这条历史记录吗？'}
            </AlertDialogDescription>
