import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { PageHeader } from '@/Components/ui/page-header'
import { useAccounts, useTasks } from '../hooks/useTasks'
import { useAccountGroups } from '../hooks/useAccountGroups'
import { usePublishStore } from '../stores/publishStore'
import { Send } from 'lucide-react'
import { PublishSuccessBanner } from '../features/publish/PublishSuccessBanner'
import { PublishStatsBar } from '../features/publish/PublishStatsBar'
import { PublishWizard } from '../features/publish/wizard/PublishWizard'
import type { TaskItem } from '@/api/client'
import type { Tone } from '@/lib/tone'

/**
 * OPT-3F: shared storage key with AppShell's sidebar collapsed state. The
 * keys live alongside each other so an operator who toggles both panels
 * closed sees consistent behaviour across `/publish` and the rest of the
 * shell. The two keys are independent (`sau-publish-ai-collapsed` vs.
 * `sau-sidebar-collapsed`); keeping them separate means clearing one
 * leaves the other intact.
 */
/**
 * OPT-V-2: derive a single Tone from intersection of `lastTaskIds` and
 * the polled `tasks` list. Returns null (muted) when there's nothing to
 * report — i.e. `lastTaskIds` empty.
 *
 * Mapping:
 *   - no last-submit yet                              → `null` (muted)
 *   - any task with `status ∈ {'pending','running'}` → `'warning'` (in-flight, pulse)
 *   - all last tasks resolved with `code === 0`     → `'success'` (green)
 *   - any last task failed (`code != 0`) and none
 *     still pending/running                           → `'error'`   (red)
 *   - some last IDs not yet visible in polled data
 *     (data still loading)                            → `'warning'` (best guess)
 *
 * The lookup tolerates missing / undefined fields because the server
 * side `TaskItem` type marks everything optional (`status?: string`,
 * `code?: number | null`). An unknown-shape task is treated as warning
 * rather than null so the chip stays informative while we wait for
 * the polling cycle to settle.
 */
function deriveLastTaskTone(tasks: TaskItem[], lastTaskIds: string[]): Tone | null {
  if (lastTaskIds.length === 0) return null
  const looked = lastTaskIds
    .map((id) => tasks.find((task) => task.task_id === id))
    .filter((task): task is TaskItem => Boolean(task))
  if (looked.length === 0) return 'warning'
  if (looked.some((task) => task.status === 'pending' || task.status === 'running')) {
    return 'warning'
  }
  const hasFailure = looked.some((task) => task.code !== undefined && task.code !== null && task.code !== 0)
  if (hasFailure) return 'error'
  return 'success'
}

/**
 * Two-column publish-center layout.
 *
 * Below lg (default 1024px): form spans full width, AI assistant is hidden
 * and surfaced via a floating action button → bottom-sheet drawer. We use
 * lg (not md=768) so the form keeps enough horizontal room for its
 * multi-select platform picker, dropzone, and schedule picker.
 *
 * lg and up: form takes the left 60%, AI assistant takes the right 40%
 * (resolves to `grid-cols-[3fr_2fr]`). OPT-3F adds `PanelRightClose` →
 * `PanelRightClose` toggle: when collapsed, the AI sidebar becomes a
 * 60px-wide rail (mirroring the main AppShell sidebar's collapsed-rail
 * pattern) and the form stretches to `[1fr_60px]`. State persists to
 * `localStorage['sau-publish-ai-collapsed']` so refresh keeps the
 * user's choice. The preview that used to live in its own aside is
 * now integrated into the AI sidebar as a collapsible section at the
 * bottom of the panel.
 */
export default function PublishPage() {
  const navigate = useNavigate()
  const { data: accountOptions = [], refetch: refetchAccounts } = useAccounts()
  const { data: groups = [] } = useAccountGroups()
  const { data: tasks = [] } = useTasks()
  const lastTaskIds = usePublishStore((s) => s.lastTaskIds)
  const submitSuccess = usePublishStore((s) => s.submitSuccess)
  const setLastTaskIds = usePublishStore((s) => s.setLastTaskIds)
  const setSubmitSuccess = usePublishStore((s) => s.setSubmitSuccess)

  // OPT-V-2: real-time tone for the "最近提交" stats card.
  const lastTaskTone = useMemo(() => deriveLastTaskTone(tasks, lastTaskIds), [tasks, lastTaskIds])

  // The wizard owns its own mode/files/content state via usePublishWizardStore.
  // PublishPage only retains the AI sidebar state, submit-success flow, and
  // the auto-navigate countdown — all of which are orthogonal to the
  // wizard's internal step navigation.
  // OPT-3I: cancellable auto-navigate. Replaces the previous 1500 ms
  // one-shot `setTimeout` with a per-second tick so the banner can
  // surface a countdown ("Xs 后跳转") and a user-clickable 取消
  // escape hatch. The interval is held in a ref because unmount
  // cleanup must reach the live setInterval handle; state alone
  // can't reliably reach into a stale interval.
  const [navigateCountdown, setNavigateCountdown] = useState<number | null>(null)
  const navigateIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null)

  const NAVIGATE_AFTER_MS = 4000
  const NAVIGATE_TICK_MS = 1000

  /**
   * Stop the auto-navigate countdown — clear interval, drop the ref,
   * reset visible countdown to null. Called by the manual-navigate
   * path AND the cancel button; the navigation itself (when countdown
   * reaches 0) is handled by a separate useEffect so the setState
   * updater stays pure.
   */
  const stopAutoNavigate = useCallback(() => {
    if (navigateIntervalRef.current) {
      clearInterval(navigateIntervalRef.current)
      navigateIntervalRef.current = null
    }
    setNavigateCountdown(null)
  }, [])

  // OPT-3I: when the countdown reaches zero, fire the navigation.
  // Lives in a useEffect (rather than inside the interval callback)
  // so the setState updater stays pure and there's exactly one place
  // that decides "jump to /tasks now". Cancel + manual-navigate both
  // short-circuit by setting `navigateCountdown` to null first, so
  // this branch only fires on natural expiry.
  useEffect(() => {
    if (navigateCountdown === 0) {
      stopAutoNavigate()
      navigate('/tasks')
    }
  }, [navigateCountdown, navigate, stopAutoNavigate])

  // Clear pending interval on unmount.
  useEffect(() => {
    return () => {
      if (navigateIntervalRef.current) clearInterval(navigateIntervalRef.current)
    }
  }, [])

  const handleGoToTasks = useCallback(() => {
    stopAutoNavigate()
    navigate('/tasks')
  }, [navigate, stopAutoNavigate])

  const scheduleNavigateAfterSubmit = useCallback(() => {
    stopAutoNavigate()
    const initialCountdown = Math.round(NAVIGATE_AFTER_MS / NAVIGATE_TICK_MS) // 4
    setNavigateCountdown(initialCountdown)
    navigateIntervalRef.current = setInterval(() => {
      setNavigateCountdown((prev) => (prev !== null && prev > 0 ? prev - 1 : prev))
    }, NAVIGATE_TICK_MS)
  }, [stopAutoNavigate])

  /**
   * OPT-3I: 取消 button handler. Clears the interval + drops
   * `navigateCountdown` to null, which causes the banner pill to
   * disappear (`cancelCountdown === null` ⇒ pill hidden). Banner
   * itself stays because `submitSuccess` is untouched — the user
   * can still click "查看任务状态" to navigate manually.
   */
  const handleCancelAutoNavigate = useCallback(() => {
    stopAutoNavigate()
  }, [stopAutoNavigate])

  // The wizard's GroupPublishSelector handles its own advanced-section
  // highlighting internally. The old OPT-3G cross-component accordion
  // coordination is no longer needed since the wizard encapsulates the
  // full form flow.

  const handleSubmitSuccess = useCallback(
    (info: { count: number; taskIds: string[]; failedCount: number; mode: '视频' | '图文' }) => {
      setLastTaskIds(info.taskIds)
      setSubmitSuccess({ count: info.count, mode: info.mode, taskIds: info.taskIds })
      scheduleNavigateAfterSubmit()
    },
    [setLastTaskIds, setSubmitSuccess, scheduleNavigateAfterSubmit],
  )

  return (
    <div className="p-6">
      <PageHeader
        title="发布中心"
        description="发布视频或图文到多个平台"
        icon={<Send className="h-5 w-5 text-muted-foreground" />}
      />

      <PublishSuccessBanner
        info={submitSuccess}
        onGoToTasks={handleGoToTasks}
        cancelCountdown={navigateCountdown}
        onCancelAutoNavigate={handleCancelAutoNavigate}
      />

      <PublishStatsBar
        accountCount={accountOptions.length}
        lastTaskIds={lastTaskIds}
        lastTaskTone={lastTaskTone}
        onRefresh={() => void refetchAccounts()}
      />

      {/* ── Main content: wizard (full width) ──────────────── */}
      <div className="mt-6">
        <PublishWizard
          groups={groups}
          onSubmit={handleSubmitSuccess}
        />
      </div>

      {/* TODO: Re-wire the AI sidebar to the wizard's content store.
           The old PublishAiSidebar used form refs (videoFormRef / noteFormRef)
           which no longer exist. A follow-up PR will bridge the wizard store
           to the AI panel's formRef-based API. */}
    </div>
  )
}

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type Dispatch,
  type ReactNode,
  type SetStateAction,
} from 'react'
import { createContext, useContext } from 'react'
import { arrayMove } from '@dnd-kit/helpers'
import { useToast } from '@/Components/ui/toast'
import { api, PLATFORMS, type AccountGroup } from '@/api/client'
import {
  useAccountGroups,
  useCreateAccountGroup,
  useDeleteAccountGroup,
  useRemoveAuthorization,
  useReorderAccountGroups,
  useReorderAuthorizations,
  useRenameAccountGroup,
} from '@/hooks/useAccountGroups'

// ── Drag-end id prefixes — discriminates group vs auth drags under one
//    single-root DragDropProvider.
const GROUP_ID_PREFIX = 'group:'
const AUTH_ID_PREFIX = 'auth:'

// ── Group-name validation (mirrors backend `_validate_group_name`) ────────
const _FORBIDDEN_NAME_RE = /[/\\:*?"<>|\x00-\x1F\x7F]/
const _NAME_MAX_LEN = 64

export type GroupNameValidation =
  | { ok: true; cleaned: string }
  | { ok: false; message: string }

export function validateGroupName(value: unknown): GroupNameValidation {
  if (typeof value !== 'string') return { ok: false, message: '分组名不能为空' }
  const cleaned = value.trim()
  if (!cleaned) return { ok: false, message: '分组名不能为空' }
  if (cleaned.length > _NAME_MAX_LEN) {
    return { ok: false, message: `分组名长度不能超过 ${_NAME_MAX_LEN} 个字符` }
  }
  if (_FORBIDDEN_NAME_RE.test(cleaned)) {
    return { ok: false, message: '分组名包含不允许的字符（/\\:*?"<>|）' }
  }
  return { ok: true, cleaned }
}

// ── Drag-end event shape used by GroupGridArea + SortableAuthorizationItem. ──
type DragEndEvent = {
  operation: {
    target: { id: string | number } | null
    source: { id: string | number } | null
  }
}

// ── State context (values that change on render / server updates) ────────
// NOTE: React Query useMutation objects are intentionally NOT passed
// through context — they return new object identities on every render,
// which destabilises useMemo deps and triggers "Maximum update depth
// exceeded".  Instead we expose only the primitive isPending flags that
// consumers need for loading spinners / button-disabled state.
export type AccountsState = {
  groups: AccountGroup[]
  isLoading: boolean
  refetch: () => void

  isCreatePending: boolean
  isRenamePending: boolean
  isReorderInFlight: boolean

  localGroups: AccountGroup[]
  filteredGroups: AccountGroup[]

  searchQuery: string
  validityFilter: 'all' | 'valid' | 'invalid'
  viewMode: 'grid' | 'list'
  selectedIds: Set<number>

  newGroupName: string
  createDialogOpen: boolean
  batchDeleteOpen: boolean
  authorizeDialogOpen: boolean
  renameDialogOpen: boolean
  renameDialogGroupId: number | null
  renameDialogCurrentName: string
  selectedGroupId: number | null
  selectedPlatform: string
  loginModalOpen: boolean

  isCheckingStatus: boolean
}

// ── Dispatch context ─────────────────────────────────────────────────────
export type AccountsDispatch = {
  setSearchQuery: (q: string) => void
  setValidityFilter: Dispatch<SetStateAction<'all' | 'valid' | 'invalid'>>
  setViewMode: Dispatch<SetStateAction<'grid' | 'list'>>
  setSelectedIds: Dispatch<SetStateAction<Set<number>>>
  setNewGroupName: (n: string) => void
  setCreateDialogOpen: (o: boolean) => void
  setBatchDeleteOpen: (o: boolean) => void
  setAuthorizeDialogOpen: (o: boolean) => void
  setSelectedPlatform: (p: string) => void
  setLoginModalOpen: (o: boolean) => void
  setRenameDialogOpen: (o: boolean) => void

  handleDragStart: () => void
  handleDragEnd: (event: DragEndEvent) => void

  handleSelectGroup: (id: number, checked: boolean) => void
  handleSelectAll: () => void
  handleBatchDelete: () => Promise<void>
  handleCreateGroup: () => Promise<void>
  handleDeleteGroup: (groupId: number, name: string) => Promise<void>
  handleStartRename: (groupId: number, currentName: string) => void
  handleRename: (groupId: number, newName: string) => Promise<void>
  handleStartAuthorize: (groupId: number) => void
  handleAuthorize: () => void
  handleRemoveAuth: (groupId: number, platform: string) => Promise<void>
  handleClearSearch: () => void
  handleCheckAllStatus: () => Promise<void>

  getPlatformLabel: (value: string) => string
}

const AccountsStateCtx = createContext<AccountsState | null>(null)
const AccountsDispatchCtx = createContext<AccountsDispatch | null>(null)

const _EMPTY_GROUPS: AccountGroup[] = []

export function AccountsProvider({ children }: { children: ReactNode }) {
  const { addToast } = useToast()

  // ── server ──
  const { data: groups = _EMPTY_GROUPS, isLoading, refetch } = useAccountGroups()
  const createGroup = useCreateAccountGroup()
  const deleteGroup = useDeleteAccountGroup()
  const renameGroup = useRenameAccountGroup()
  const removeAuth = useRemoveAuthorization()
  const reorderGroups = useReorderAccountGroups()
  const reorderAuths = useReorderAuthorizations()

  // ── local/dialog UI state ──
  const [newGroupName, setNewGroupName] = useState('')
  const [createDialogOpen, setCreateDialogOpen] = useState(false)
  const [authorizeDialogOpen, setAuthorizeDialogOpen] = useState(false)
  const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null)
  const [selectedPlatform, setSelectedPlatform] = useState('')
  const [loginModalOpen, setLoginModalOpen] = useState(false)
  const [renameDialogOpen, setRenameDialogOpen] = useState(false)
  const [renameDialogGroupId, setRenameDialogGroupId] = useState<number | null>(null)
  const [renameDialogCurrentName, setRenameDialogCurrentName] = useState('')
  const [searchQuery, setSearchQuery] = useState('')
  const [validityFilter, setValidityFilter] = useState<'all' | 'valid' | 'invalid'>('all')
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid')
  const [selectedIds, setSelectedIds] = useState<Set<number>>(new Set())
  const [batchDeleteOpen, setBatchDeleteOpen] = useState(false)
  const [isCheckingStatus, setIsCheckingStatus] = useState(false)

  // ── optimistic local copy of server data; drag guard prevents mid-drag clobbers ──
  const isDraggingRef = useRef(false)
  const [localGroups, setLocalGroups] = useState<AccountGroup[]>(groups)
  useEffect(() => {
    if (!isDraggingRef.current) {
      setLocalGroups(groups)
    }
  }, [groups])

  // ── ref-mirrors so dispatch handlers can read latest state WITHOUT
  //    capturing the state in useCallback deps (keeps dispatch identity
  //    stable across state updates). Same trick mirrored for the
  //    react-query mutation objects — their identity changes whenever
  //    isPending toggles, so handlers must NOT close over them directly.
  const localGroupsRef = useRef(localGroups)
  useEffect(() => {
    localGroupsRef.current = localGroups
  }, [localGroups])
  const filteredGroupsRef = useRef<AccountGroup[]>([])
  const selectedIdsRef = useRef(selectedIds)
  useEffect(() => {
    selectedIdsRef.current = selectedIds
  }, [selectedIds])
  const groupsRef = useRef(groups)
  useEffect(() => {
    groupsRef.current = groups
  }, [groups])
  const newGroupNameRef = useRef(newGroupName)
  useEffect(() => {
    newGroupNameRef.current = newGroupName
  }, [newGroupName])
  const selectedGroupIdRef = useRef(selectedGroupId)
  useEffect(() => {
    selectedGroupIdRef.current = selectedGroupId
  }, [selectedGroupId])
  const selectedPlatformRef = useRef(selectedPlatform)
  useEffect(() => {
    selectedPlatformRef.current = selectedPlatform
  }, [selectedPlatform])

  // mutation refs — capture the live mutate functions on every render so
  // stable handlers can call them without keeping mutation objects in deps.
  const createMutateAsyncRef = useRef(createGroup.mutateAsync)
  useEffect(() => {
    createMutateAsyncRef.current = createGroup.mutateAsync
  }, [createGroup.mutateAsync])
  const deleteMutateAsyncRef = useRef(deleteGroup.mutateAsync)
  useEffect(() => {
    deleteMutateAsyncRef.current = deleteGroup.mutateAsync
  }, [deleteGroup.mutateAsync])
  const renameMutateAsyncRef = useRef(renameGroup.mutateAsync)
  useEffect(() => {
    renameMutateAsyncRef.current = renameGroup.mutateAsync
  }, [renameGroup.mutateAsync])
  const removeAuthMutateAsyncRef = useRef(removeAuth.mutateAsync)
  useEffect(() => {
    removeAuthMutateAsyncRef.current = removeAuth.mutateAsync
  }, [removeAuth.mutateAsync])
  const reorderMutateRef = useRef(reorderGroups.mutate)
  useEffect(() => {
    reorderMutateRef.current = reorderGroups.mutate
  }, [reorderGroups.mutate])
  const reorderAuthsMutateRef = useRef(reorderAuths.mutate)
  useEffect(() => {
    reorderAuthsMutateRef.current = reorderAuths.mutate
  }, [reorderAuths.mutate])
  const refetchRef = useRef(refetch)
  useEffect(() => {
    refetchRef.current = refetch
  }, [refetch])

  const isReorderInFlight = reorderGroups.isPending || reorderAuths.isPending

  // ── stable platform-label helper (MUST be defined before filteredGroups
  //     useMemo to avoid Temporal Dead Zone access).
  const getPlatformLabel = useCallback(
    (value: string) => PLATFORMS.find((p) => p.value === value)?.label ?? value,
    [],
  )

  // Belt-and-braces: validityFilter is held in a useState typed as the
  // narrow union 'all' | 'valid' | 'invalid', but if a future migration
  // widens the type or an older saved value is replayed, we want a safe
  // fallback rather than a silent miss.
  const safeValidityFilter: 'all' | 'valid' | 'invalid' =
    validityFilter === 'valid' || validityFilter === 'invalid'
      ? validityFilter
      : 'all'

  // ── derived: filteredGroups ───────────────────────────────────────
  // Pipeline: localGroups → safeValidityFilter → searchQuery trim+match.
  // Validity filter runs first so an empty group with zero auths is hidden
  // from both 有效 and 失效 views (only groups with at least one all-valid
  // auth qualify for 有效; only groups containing an invalid auth qualify
  // for 失效 — empty groups have neither and so live only in 全部).
  // Magic-string 有效/失效 search-keyword matching was removed; the toolbar
  // exposes this as a segmented control so the contract is explicit.
  const filteredGroups = useMemo(() => {
    let result = localGroups
    if (safeValidityFilter === 'valid') {
      result = result.filter(
        (g) => g.authorizations.length > 0 && g.authorizations.every((a) => a.valid),
      )
    } else if (safeValidityFilter === 'invalid') {
      result = result.filter((g) => g.authorizations.some((a) => !a.valid))
    }

    const query = searchQuery.trim().toLowerCase()
    if (!query) return result
    return result.filter((group) => {
      const nameMatch = group.name.toLowerCase().includes(query)
      const platformMatch = group.authorizations.some(
        (auth) =>
          auth.platform.toLowerCase().includes(query) ||
          getPlatformLabel(auth.platform).toLowerCase().includes(query),
      )
      return nameMatch || platformMatch
    })
  }, [localGroups, searchQuery, safeValidityFilter, getPlatformLabel])
  useEffect(() => {
    filteredGroupsRef.current = filteredGroups
  }, [filteredGroups])

  // ── dnd handlers ──
  // Optimistic mutate-first-then-callback. The onError path fires a
  // refetch; the server→local useEffect then clobbers any stuck optimistic
  // order. stable deps (`[]` or just `addToast`) keep identity stable.
  const handleDragStart = useCallback(() => {
    isDraggingRef.current = true
  }, [])

  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      isDraggingRef.current = false
      const { target, source } = event.operation
      if (!target || !source) return

      const sourceId = String(source.id)
      const targetId = String(target.id)
      const snapshot = localGroupsRef.current

      // Group reorder branch: `group:<id>` on both sides.
      if (
        sourceId.startsWith(GROUP_ID_PREFIX) &&
        targetId.startsWith(GROUP_ID_PREFIX)
      ) {
        const sourceGroupId = Number(sourceId.slice(GROUP_ID_PREFIX.length))
        const targetGroupId = Number(targetId.slice(GROUP_ID_PREFIX.length))
        const sourceIndex = snapshot.findIndex((g) => g.id === sourceGroupId)
        const targetIndex = snapshot.findIndex((g) => g.id === targetGroupId)
        if (
          sourceIndex === -1 ||
          targetIndex === -1 ||
          sourceIndex === targetIndex
        ) {
          return
        }
        const newGroups = arrayMove(snapshot, sourceIndex, targetIndex)
        setLocalGroups(newGroups)
        reorderMutateRef.current(newGroups.map((g) => g.id), {
          onError: () => {
            addToast('保存顺序失败，正在恢复…', 'error')
            refetchRef.current()
          },
        })
        return
      }

      // Auth reorder branch: `auth:<groupId>:<authId>` on both sides.
      // Cross-group drags are silently ignored — auths are tied to a group.
      if (
        sourceId.startsWith(AUTH_ID_PREFIX) &&
        targetId.startsWith(AUTH_ID_PREFIX)
      ) {
        const [, srcGroupRaw, srcAuthRaw] = sourceId.split(':')
        const [, tgtGroupRaw, tgtAuthRaw] = targetId.split(':')
        const sourceGroupId = Number(srcGroupRaw)
        const targetGroupId = Number(tgtGroupRaw)
        if (sourceGroupId !== targetGroupId) return
        const sourceAuthId = Number(srcAuthRaw)
        const targetAuthId = Number(tgtAuthRaw)
        const groupIdx = snapshot.findIndex((g) => g.id === sourceGroupId)
        if (groupIdx === -1) return
        const authList = snapshot[groupIdx].authorizations
        const sourceIndex = authList.findIndex((a) => a.id === sourceAuthId)
        const targetIndex = authList.findIndex((a) => a.id === targetAuthId)
        if (
          sourceIndex === -1 ||
          targetIndex === -1 ||
          sourceIndex === targetIndex
        ) {
          return
        }
        const newAuths = arrayMove(authList, sourceIndex, targetIndex)
        setLocalGroups((prev) =>
          prev.map((g) =>
            g.id === sourceGroupId ? { ...g, authorizations: newAuths } : g,
          ),
        )
        reorderAuthsMutateRef.current(
          { groupId: sourceGroupId, authIds: newAuths.map((a) => a.id) },
          {
            onError: () => {
              addToast('保存顺序失败，正在恢复…', 'error')
              refetchRef.current()
            },
          },
        )
      }
    },
    [addToast],
  )

  // ── selection handlers (refs only — stable identity) ──
  const handleSelectGroup = useCallback((id: number, checked: boolean) => {
    setSelectedIds((prev) => {
      const next = new Set(prev)
      if (checked) next.add(id)
      else next.delete(id)
      return next
    })
  }, [])

  const handleSelectAll = useCallback(() => {
    const filtered = filteredGroupsRef.current
    const current = selectedIdsRef.current
    if (current.size === filtered.length && filtered.length > 0) {
      setSelectedIds(new Set())
    } else {
      setSelectedIds(new Set(filtered.map((g) => g.id)))
    }
  }, [])

  // ── batch / create / delete / rename / remove-auth handlers — all
  //    stable; they read mutate fns via refs and capture `addToast`
  //    only by reference. addToast identity is stable (useToast wraps
  //    it in useCallback per toast.tsx line 46).
  const handleBatchDelete = useCallback(async () => {
    const ids = Array.from(selectedIdsRef.current)
    const count = ids.length
    const settled = await Promise.allSettled(
      ids.map((id) => deleteMutateAsyncRef.current(id)),
    )
    const failed = settled.filter((r) => {
      if (r.status === 'rejected') return true
      return r.value?.success === false
    })
    const succeeded = count - failed.length

    setSelectedIds(new Set())
    setBatchDeleteOpen(false)

    if (failed.length === 0) {
      addToast(`已删除 ${count} 个分组`, 'success')
    } else if (succeeded === 0) {
      addToast(`${failed.length} 个分组删除失败`, 'error')
    } else {
      addToast(
        `成功删除 ${succeeded}/${count} 个分组，${failed.length} 个失败`,
        'warning',
      )
    }
  }, [addToast])

  const handleCreateGroup = useCallback(async () => {
    const trimmed = newGroupNameRef.current.trim()
    if (!trimmed) {
      addToast('请输入账号分组名称', 'warning')
      return
    }
    try {
      const result = await createMutateAsyncRef.current(trimmed)
      if (result.success) {
        addToast(`分组 "${trimmed}" 创建成功`, 'success')
        setNewGroupName('')
        setCreateDialogOpen(false)
      } else {
        addToast(result.message || '创建失败', 'error')
      }
    } catch {
      addToast('创建请求失败', 'error')
    }
  }, [addToast])

  const handleDeleteGroup = useCallback(
    async (groupId: number, name: string) => {
      try {
        const result = await deleteMutateAsyncRef.current(groupId)
        if (result.success) {
          addToast(`分组 "${name}" 已删除`, 'success')
        } else {
          addToast(result.message || '删除失败', 'error')
        }
      } catch {
        addToast('删除请求失败', 'error')
      }
    },
    [addToast],
  )

  const handleStartRename = useCallback((groupId: number, currentName: string) => {
    setRenameDialogGroupId(groupId)
    setRenameDialogCurrentName(currentName)
    setRenameDialogOpen(true)
  }, [])

  const handleRename = useCallback(
    async (groupId: number, newName: string) => {
      const v = validateGroupName(newName)
      if (!v.ok) {
        addToast(v.message, 'warning')
        return
      }
      try {
        const result = await renameMutateAsyncRef.current({
          groupId,
          name: v.cleaned,
        })
        if (result.success) {
          addToast(`分组已重命名为 "${v.cleaned}"`, 'success')
          setRenameDialogOpen(false)
          setRenameDialogGroupId(null)
          setRenameDialogCurrentName('')
        } else {
          addToast(result.message || '重命名失败', 'error')
        }
      } catch {
        addToast('重命名请求失败', 'error')
      }
    },
    [addToast],
  )

  const handleStartAuthorize = useCallback((groupId: number) => {
    setSelectedGroupId(groupId)
    setSelectedPlatform('')
    setAuthorizeDialogOpen(true)
  }, [])

  // Note: refs declared above the handleAuthorize definition so the
  // hook-order lint/eslint rule is satisfied (see selectedGroupIdRef /
  // selectedPlatformRef at the top of the file).
  const handleAuthorize = useCallback(() => {
    const gid = selectedGroupIdRef.current
    const platform = selectedPlatformRef.current
    if (!gid || !platform) {
      addToast('请选择平台', 'warning')
      return
    }
    setAuthorizeDialogOpen(false)
    setLoginModalOpen(true)
  }, [addToast])

  const handleRemoveAuth = useCallback(
    async (groupId: number, platform: string) => {
      try {
        const result = await removeAuthMutateAsyncRef.current({
          groupId,
          platform,
        })
        if (result.success) {
          addToast(`已移除 ${platform} 授权`, 'success')
        } else {
          addToast(result.message || '移除失败', 'error')
        }
      } catch {
        addToast('移除请求失败', 'error')
      }
    },
    [addToast],
  )

  const handleClearSearch = useCallback(() => setSearchQuery(''), [])

  const handleCheckAllStatus = useCallback(async () => {
    if (groupsRef.current.length === 0) return
    setIsCheckingStatus(true)
    try {
      const res = await api.checkAllAccounts()
      if (res.success && res.data) {
        const total = res.data.length
        const valid = res.data.filter((d) => d.quick?.valid === true).length
        const invalid = total - valid
        if (total === 0) {
          addToast('当前没有可检测的授权账号', 'info')
        } else if (invalid === 0) {
          addToast(`已检测 ${total} 个授权，全部有效`, 'success')
        } else {
          addToast(
            `已检测 ${total} 个授权：${valid} 个有效，${invalid} 个失效，请重新登录`,
            'warning',
          )
        }
        refetchRef.current()
      } else {
        addToast('检测请求失败', 'error')
      }
    } catch {
      addToast('检测请求失败，请检查后端连接', 'error')
    } finally {
      setIsCheckingStatus(false)
    }
  }, [addToast])

  // ── dispatch object — stable identity when handlers above don't churn ──
  const dispatch = useMemo<AccountsDispatch>(
    () => ({
      setSearchQuery,
      setValidityFilter,
      setViewMode,
      setSelectedIds,
      setNewGroupName,
      setCreateDialogOpen,
      setBatchDeleteOpen,
      setAuthorizeDialogOpen,
      setSelectedPlatform,
      setLoginModalOpen,
      setRenameDialogOpen,
      handleDragStart,
      handleDragEnd,
      handleSelectGroup,
      handleSelectAll,
      handleBatchDelete,
      handleCreateGroup,
      handleDeleteGroup,
      handleStartRename,
      handleRename,
      handleStartAuthorize,
      handleAuthorize,
      handleRemoveAuth,
      handleClearSearch,
      handleCheckAllStatus,
      getPlatformLabel,
    }),
    [
      handleDragStart,
      handleDragEnd,
      handleSelectGroup,
      handleSelectAll,
      handleBatchDelete,
      handleCreateGroup,
      handleDeleteGroup,
      handleStartRename,
      handleRename,
      handleStartAuthorize,
      handleAuthorize,
      handleRemoveAuth,
      handleClearSearch,
      handleCheckAllStatus,
      getPlatformLabel,
    ],
  )

  const state = useMemo<AccountsState>(
    () => ({
      groups,
      isLoading,
      refetch,
      isCreatePending: createGroup.isPending,
      isRenamePending: renameGroup.isPending,
      isReorderInFlight,
      localGroups,
      filteredGroups,
      searchQuery,
      validityFilter,
      viewMode,
      selectedIds,
      newGroupName,
      createDialogOpen,
      batchDeleteOpen,
      authorizeDialogOpen,
      renameDialogOpen,
      renameDialogGroupId,
      renameDialogCurrentName,
      selectedGroupId,
      selectedPlatform,
      loginModalOpen,
      isCheckingStatus,
    }),
    [
      groups,
      isLoading,
      refetch,
      createGroup.isPending,
      renameGroup.isPending,
      isReorderInFlight,
      localGroups,
      filteredGroups,
      searchQuery,
      validityFilter,
      viewMode,
      selectedIds,
      newGroupName,
      createDialogOpen,
      batchDeleteOpen,
      authorizeDialogOpen,
      renameDialogOpen,
      renameDialogGroupId,
      renameDialogCurrentName,
      selectedGroupId,
      selectedPlatform,
      loginModalOpen,
      isCheckingStatus,
    ],
  )

  return (
    <AccountsDispatchCtx.Provider value={dispatch}>
      <AccountsStateCtx.Provider value={state}>{children}</AccountsStateCtx.Provider>
    </AccountsDispatchCtx.Provider>
  )
}

export function useAccountsState(): AccountsState {
  const ctx = useContext(AccountsStateCtx)
  if (!ctx) throw new Error('useAccountsState must be used inside <AccountsProvider>')
  return ctx
}

export function useAccountsDispatch(): AccountsDispatch {
  const ctx = useContext(AccountsDispatchCtx)
  if (!ctx) throw new Error('useAccountsDispatch must be used inside <AccountsProvider>')
  return ctx
}

import { memo, useEffect, useState } from 'react'
import { Button } from '@/Components/ui/button'
import { Input } from '@/Components/ui/input'
import {
  CheckSquare,
  CircleDot,
  LayoutGrid,
  List,
  Loader2,
  Search,
  Square,
  Trash,
  X,
} from 'lucide-react'
import { cn } from '@/lib/utils'
import { toneDotStyle, type Tone } from '@/lib/tone'
import { useAccountsDispatch, useAccountsState } from './AccountsProvider'

/** All four shape axes (value / label / icon / tone) are present on every
 *  item so iterating `VALIDITY_OPTIONS` doesn't fall into a discriminated
 *  union with missing properties (TS2339 in render). 'all' has `tone = null`
 *  and renders no decoration — it's the "no filter" baseline. The `tone`
 *  field is `Tone | null` (renamed from `dotClass: string | null`) so the
 *  filter decoration pulls colour from `@/lib/tone.ts` rather than from
 *  the deleted `.status-dot-{valid,invalid}` CSS rules. */
const VALIDITY_OPTIONS: ReadonlyArray<{
  value: 'all' | 'valid' | 'invalid'
  label: string
  icon: typeof CircleDot | null
  tone: Tone | null
}> = [
  { value: 'all', label: '全部', icon: null, tone: null },
  { value: 'valid', label: '有效', icon: CircleDot, tone: 'success' },
  { value: 'invalid', label: '失效', icon: null, tone: 'error' },
] as const

/**
 * Toolbar at the top of the accounts page: search input + validity filter
 * (paired as "filter controls"), batch-delete bar (only when something is
 * selected), select-all + view toggle + reorder-in-flight chip.
 *
 * Search state is intentionally LOCAL with a 120ms debounce — typing must
 * not churn the dispatch context identity (which memoized children depend
 * on to skip re-renders).
 */
function GroupToolbarImpl() {
  const state = useAccountsState()
  const dispatch = useAccountsDispatch()

  // ── local search state with debounce ──
  const [localSearch, setLocalSearch] = useState(state.searchQuery)
  useEffect(() => {
    const handle = setTimeout(() => {
      if (localSearch !== state.searchQuery) {
        dispatch.setSearchQuery(localSearch)
      }
    }, 120)
    return () => clearTimeout(handle)
  }, [localSearch, state.searchQuery, dispatch])

  // ── keep local in sync if dispatch changes from outside (clear button etc.) ──
  useEffect(() => {
    setLocalSearch(state.searchQuery)
  }, [state.searchQuery])

  const allSelected =
    state.selectedIds.size === state.filteredGroups.length &&
    state.filteredGroups.length > 0

  /** Decorative dot/decoration rendering right after each segmented button
   *  label. Centralised here to keep the segmented map below readable. */
  const renderValidityIcon = (opt: (typeof VALIDITY_OPTIONS)[number]) => {
    if (opt.icon) {
      const Icon = opt.icon
      // lucide-react icons propagate the `style` prop down to the SVG where
      // `toneDotStyle(tone)` paints the canonical --status-{tone}-fg
      // background + 40% halo (replaces the deleted `.status-dot-{valid,
      // invalid}` CSS rules previously applied via `className`).
      return <Icon className="h-3 w-3 mr-1" style={toneDotStyle(opt.tone)} />
    }
    if (opt.tone) {
      return <span className="mr-1.5 h-1.5 w-1.5 rounded-full" style={toneDotStyle(opt.tone)} />
    }
    return null
  }

  return (
    <div className="flex items-center gap-3 flex-wrap">
      {/* Search with keyword hint */}
      <div className="relative flex-1 min-w-[200px] max-w-md">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground/50" />
        <Input
          placeholder="搜索分组名称、平台..."
          value={localSearch}
          onChange={(e) => setLocalSearch(e.target.value)}
          className="pl-9 pr-16"
          data-search-input
        />
        {!localSearch && (
          <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-1 pointer-events-none">
            <kbd className="kbd-hint">/</kbd>
          </div>
        )}
        {localSearch && (
          <button
            type="button"
            onClick={() => {
              setLocalSearch('')
              dispatch.handleClearSearch()
            }}
            className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
            aria-label="Clear search"
          >
            <X className="h-4 w-4" />
          </button>
        )}
      </div>

      {/* Validity filter — visually paired with search input (both are
          "filter controls"); replaces the magic 已/失效 search-keyword branch. */}
      <div className="flex items-center bg-muted/50 rounded-lg p-0.5 border border-border/50">
        {VALIDITY_OPTIONS.map((opt) => {
          const active = state.validityFilter === opt.value
          return (
            <button
              key={opt.value}
              type="button"
              onClick={() => dispatch.setValidityFilter(opt.value)}
              className={cn(
                'flex items-center justify-center h-7 px-2.5 rounded-md text-[11px] font-medium transition-all duration-200',
                active
                  ? 'bg-background text-foreground shadow-sm'
                  : 'text-muted-foreground/60 hover:text-muted-foreground',
              )}
              aria-pressed={active}
              aria-label={`筛选：${opt.label}`}
            >
              {renderValidityIcon(opt)}
              {opt.label}
            </button>
          )
        })}
      </div>

      {/* Batch actions (only when something is selected) */}
      {state.selectedIds.size > 0 && (
        <div className="flex items-center gap-2 animate-in fade-in slide-in-from-left-2">
          <span className="text-sm text-muted-foreground">
            已选择 {state.selectedIds.size} 项
          </span>
          <Button
            variant="destructive"
            size="sm"
            onClick={() => dispatch.setBatchDeleteOpen(true)}
          >
            <Trash className="h-4 w-4 mr-1" />
            批量删除
          </Button>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => dispatch.setSelectedIds(new Set())}
          >
            取消选择
          </Button>
        </div>
      )}

      {/* Select-all + view toggle + reorder-in-flight chip */}
      <div className="flex items-center gap-1.5">
        <Button
          variant={allSelected ? 'secondary' : 'ghost'}
          size="sm"
          onClick={dispatch.handleSelectAll}
          className="text-muted-foreground h-8"
        >
          {allSelected ? (
            <CheckSquare className="h-4 w-4 mr-1" />
          ) : (
            <Square className="h-4 w-4 mr-1" />
          )}
          全选
        </Button>

        {/* Segmented view toggle */}
        <div className="flex items-center bg-muted/50 rounded-lg p-0.5 border border-border/50">
          <button
            type="button"
            onClick={() => dispatch.setViewMode('grid')}
            className={cn(
              'flex items-center justify-center h-7 w-7 rounded-md transition-all duration-200',
              state.viewMode === 'grid'
                ? 'bg-background text-foreground shadow-sm'
                : 'text-muted-foreground/50 hover:text-muted-foreground',
            )}
            aria-label="Grid view"
          >
            <LayoutGrid className="h-3.5 w-3.5" />
          </button>
          <button
            type="button"
            onClick={() => dispatch.setViewMode('list')}
            className={cn(
              'flex items-center justify-center h-7 w-7 rounded-md transition-all duration-200',
              state.viewMode === 'list'
                ? 'bg-background text-foreground shadow-sm'
                : 'text-muted-foreground/50 hover:text-muted-foreground',
            )}
            aria-label="List view"
          >
            <List className="h-3.5 w-3.5" />
          </button>
        </div>

        {state.isReorderInFlight && (
          <div
            role="status"
            aria-live="polite"
            className="flex items-center gap-1.5 px-2.5 py-1 rounded-md bg-foreground/[0.04] animate-in fade-in slide-in-from-left-2 duration-200"
          >
            <Loader2 className="h-3 w-3 animate-spin text-muted-foreground" />
            <span className="text-[11px] text-muted-foreground whitespace-nowrap">
              保存顺序中…
            </span>
          </div>
        )}
      </div>
    </div>
  )
}

export const GroupToolbar = memo(GroupToolbarImpl)

import { memo, useMemo, type ReactNode } from 'react'
import { ArrowUpRight, Folders, Loader2, Plus, Send, ShieldCheck } from 'lucide-react'
import { PLATFORMS, type TaskItem } from '@/api/client'
import { useAccountGroups } from '@/hooks/useAccountGroups'
import { useTasks } from '@/hooks/useTasks'
import { cn } from '@/lib/utils'
import {
  rateToTone,
  toneChipClasses,
  toneDotClasses,
  type Tone,
} from '@/lib/tone'

/* ── Public overview props ──────────────────────────────────────────── */

interface HomepageOverviewProps {
  /** Triggered by the inline CTA when the user has zero groups. */
  onCreateGroup?: () => void
  /** Triggered by the "validity" tile when at least one authorization exists. */
  onCheckAllStatus?: () => void
  /** Triggered by the "recent publish" tile to navigate to /tasks. */
  onOpenTasks?: () => void
  /** Triggered by "recent publish" empty-state to navigate to /publish. */
  onOpenPublish?: () => void
}

/* ── Tone mappers ───────────────────────────────────────────────────── */

/** Maps backend task.status → Chinese label + Tone (nullable). Mirrors
 *  the union handled by TasksPage. `null` = "unknown / no data". */
function taskStatusDisplay(status?: string): { label: string; tone: Tone | null } {
  if (!status) return { label: '未知', tone: null }
  switch (status) {
    case 'success':
      return { label: '成功', tone: 'success' }
    case 'failed':
      return { label: '失败', tone: 'error' }
    case 'error':
      return { label: '异常', tone: 'error' }
    case 'pending':
      return { label: '等待', tone: 'warning' }
    case 'running':
      return { label: '运行中', tone: 'warning' }
    case 'scheduled':
      return { label: '已计划', tone: 'info' }
    default:
      return { label: status, tone: null }
  }
}

function platformLabel(value?: string): string {
  if (!value) return ''
  return PLATFORMS.find((p) => p.value === value)?.label ?? value
}

/** Compact "…​5 minutes ago" formatter — zh-CN, no seconds granularity. */
function timeAgo(iso?: string): string {
  if (!iso) return '—'
  const t = Date.parse(iso)
  if (Number.isNaN(t)) return '—'
  const diffSec = Math.max(0, Math.floor((Date.now() - t) / 1000))
  if (diffSec < 60) return '刚刚'
  const mins = Math.floor(diffSec / 60)
  if (mins < 60) return `${mins} 分钟前`
  const hrs = Math.floor(mins / 60)
  if (hrs < 24) return `${hrs} 小时前`
  const days = Math.floor(hrs / 24)
  if (days < 30) return `${days} 天前`
  return new Date(t).toLocaleDateString('zh-CN')
}

/** Mirror publish/shared.formatTaskId — ellipsises long IDs to last 10 chars. */
function compactTaskId(value?: string): string {
  if (!value) return ''
  return value.length > 14 ? `…${value.slice(-10)}` : value
}

/* ── Single stat tile ───────────────────────────────────────────────── */

interface TileProps {
  icon: ReactNode
  label: string
  value: ReactNode
  hint?: ReactNode
  /** Tone for the icon-chip background. `null` → muted neutral. */
  accent: Tone | null
  onClick?: () => void
  footer?: ReactNode
  /** Render the value with muted foreground color — signals "zero / empty"
   *  state vs primary foreground for "active / positive" data. Linear
   *  convention: tertiary ink on passive metrics, full ink on actionable ones. */
  muted?: boolean
}

function Tile({ icon, label, value, hint, accent, onClick, footer, muted }: TileProps) {
  const interactive = Boolean(onClick)
  return (
    <div
      className={cn(
        // Solid `card-refined` + relative overflow-hidden hosts the
        // absolute top-light sheen below. No transition on the base —
        // non-interactive tiles have no hover state to animate.
        'card-refined relative overflow-hidden p-4',
        // Single Tailwind arbitrary transition covers color (bg hover
        // from `.card-refined:hover`) AND transform (micro-lift)
        // under one `transition-property` declaration — avoids the
        // source-order cascade collision two separate `transition-*`
        // classes would trigger. The lift is gated alone behind
        // `motion-safe:`; color hover stays visible for reduced-motion
        // users since color is not a vestibular trigger.
        interactive && 'cursor-pointer group transition-[color,background-color,border-color,fill,stroke,transform] duration-200 motion-safe:hover:-translate-y-0.5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-background',
      )}
      onClick={onClick}
      role={interactive ? 'button' : undefined}
      tabIndex={interactive ? 0 : undefined}
      onKeyDown={
        interactive
          ? (e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault()
                onClick?.()
              }
            }
          : undefined
      }
      aria-label={interactive ? label : undefined}
    >
      {/* Linear-style top-light sheen — pale white gradient on the upper
          edge for tactile card depth. Mirrors ambient light on a real card. */}
      <span
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-white/[0.08] to-transparent"
      />

      <div className="flex items-start justify-between gap-2 mb-3">
        {/* Linear-style icon tile: tone-coloured bg+fg with inset shadow
            stacking for "raised tactile surface" feel (top highlight + bottom
            shade). 9×9 (was 8×8) matches the page-header icon for visual
            hierarchy parity across the app's chrome surfaces. */}
        <div
          className={cn(
            'relative flex h-9 w-9 items-center justify-center rounded-lg',
            // Top-only highlight: the original bottom-shade had
            // `oklch(0 0 0 / 0.04)` — black at 4% is invisible against
            // either surface. The icon tile reads as "raised" via the
            // single top-light cap alone; the bottom shade was a
            // vestigial component of the Linear template, dropped.
            'shadow-[inset_0_1px_0_oklch(1_0_0_/_0.08)]',
            toneChipClasses(accent),
          )}
        >
          {icon}
          {/* Inner top-light — sharp 1px sheen accent on the icon tile. */}
          <span
            aria-hidden="true"
            className="pointer-events-none absolute inset-x-1 top-1 h-px bg-gradient-to-r from-transparent via-white/[0.10] to-transparent"
          />
        </div>
        {interactive && (
          <ArrowUpRight
            aria-hidden="true"
            // Color shift is fine for reduced-motion users (no vestibular
            // trigger); only the transform group-hover gets motion-safe
            // gating so the chevron doesn't slide while the card stays
            // static for `prefers-reduced-motion: reduce` users.
            className="h-4 w-4 text-muted-foreground/40 group-hover:text-foreground/80 motion-safe:transition-transform motion-safe:duration-200 motion-safe:group-hover:translate-x-0.5 motion-safe:group-hover:-translate-y-0.5"
          />
        )}
      </div>

      <div className="text-[10px] font-medium uppercase tracking-wider text-muted-foreground/70">
        {label}
      </div>
      <div
        className={cn(
          'text-[26px] font-semibold tracking-tighter tabular-nums leading-none mt-1.5',
          muted ? 'text-muted-foreground/70' : 'text-foreground',
        )}
      >
        {value}
      </div>
      {hint && <div className="text-[12px] text-muted-foreground/80 mt-1.5">{hint}</div>}
      {footer && <div className="mt-2.5">{footer}</div>}
    </div>
  )
}

/* ── Public overview component ──────────────────────────────────────── */

function HomepageOverviewImpl({
  onCreateGroup,
  onCheckAllStatus,
  onOpenTasks,
  onOpenPublish,
}: HomepageOverviewProps) {
  const { data: groups = [], isLoading: isGroupsLoading } = useAccountGroups()
  const { data: tasks = [] } = useTasks()

  const metrics = useMemo(() => {
    const totalGroups = groups.length
    const auths = groups.flatMap((g) => g.authorizations)
    const authTotal = auths.length
    const authValid = auths.filter((a) => a.valid).length
    const authRate = authTotal > 0 ? authValid / authTotal : 0

    const inFlightCount = tasks.filter(
      (t) => t.status === 'pending' || t.status === 'running',
    ).length

    /* Single-pass O(N) latest-task lookup — banner only needs the most
     * recent entry, so a full sort is wasted work on 1000+ task lists. */
    const lastTask: TaskItem | undefined =
      tasks.length > 0
        ? tasks.reduce<TaskItem>((latest, t) => {
            const a = latest.created ?? ''
            const b = t.created ?? ''
            return b.localeCompare(a) > 0 ? t : latest
          }, tasks[0])
        : undefined

    return {
      totalGroups,
      authTotal,
      authValid,
      authRate,
      inFlightCount,
      lastTask,
      taskCount: tasks.length,
    }
  }, [groups, tasks])

  // Branded empty state — only shown when not loading AND the user has
  // zero groups. Skin: muted card with right-aligned primary CTA.
  if (!isGroupsLoading && metrics.totalGroups === 0) {
    return (
      <div className="rounded-xl border border-dashed border-border/60 bg-muted/20 p-4 sm:p-5 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div className="flex items-center gap-3 min-w-0">
          <div
            className={cn(
              'flex h-10 w-10 items-center justify-center rounded-xl flex-shrink-0',
              toneChipClasses('info'),
            )}
          >
            <Folders className="h-5 w-5" />
          </div>
          <div className="min-w-0">
            <div className="text-[10px] font-medium uppercase tracking-wider text-muted-foreground/70">
              账号分组
            </div>
            <div className="text-base font-semibold text-foreground mt-0.5">尚未创建分组</div>
            <div className="text-[12px] text-muted-foreground/80 mt-0.5">
              建一个分组，再开始给各平台添加授权
            </div>
          </div>
        </div>
        <button
          type="button"
          onClick={onCreateGroup}
          className={cn(
            'btn-elegant inline-flex items-center justify-center gap-1.5 rounded-md px-3.5 py-2',
            'bg-primary text-primary-foreground text-[13px] font-medium',
            'hover:opacity-90 transition-opacity self-start sm:self-auto',
          )}
        >
          <Plus className="h-4 w-4" />
          新建分组
        </button>
      </div>
    )
  }

  // Loading shells (rare because useAccountGroups is fast; cheap to render).
  if (isGroupsLoading) {
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
        {[0, 1, 2, 3].map((i) => (
          <div
            key={i}
            // Skeleton stays on `bg-card/40` (NOT `card-refined`) so the
            // `animate-pulse` 100%→50% opacity modulation is visible
            // against the half-opacity base. A solid surface damps the
            // pulse to invisibility, defeating the loading affordance —
            // this is the only place the legacy `bg-card/40` shape is
            // intentionally retained.
            className="rounded-xl border border-border/40 bg-card/40 p-4 min-h-[130px] animate-pulse"
          />
        ))}
      </div>
    )
  }

  /* Tile-level JSX inlined below so the parent controls render order
   * directly. Tile is intentionally not memo-wrapped: a fresh icon element
   * is produced each render and memo() would never hit anyway. */

  const lastStatus = taskStatusDisplay(metrics.lastTask?.status)
  const lastTileContent = metrics.lastTask ? (
    <div className="flex items-center gap-1.5 flex-wrap">
      <span
        className={cn(
          'inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium',
          toneChipClasses(lastStatus.tone),
        )}
      >
        <span className={cn('w-1.5 h-1.5 rounded-full', toneDotClasses(lastStatus.tone))} />
        {lastStatus.label}
      </span>
      <span className="text-[10px] font-mono text-muted-foreground/70">
        {compactTaskId(metrics.lastTask.task_id)}
      </span>
    </div>
  ) : null

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
      <Tile
        icon={<Folders className="h-4 w-4" />}
        label="账号分组"
        value={metrics.totalGroups}
        hint={
          metrics.authTotal > 0
            ? `${metrics.authTotal} 个平台授权`
            : '尚无平台授权'
        }
        accent="info"
      />
      <Tile
        icon={<ShieldCheck className="h-4 w-4" />}
        label="有效率"
        value={metrics.authTotal > 0 ? `${Math.round(metrics.authRate * 100)}%` : '—'}
        hint={
          metrics.authTotal > 0
            ? `${metrics.authValid} / ${metrics.authTotal} 个授权正常`
            : '暂无授权可检测'
        }
        accent={rateToTone(metrics.authRate, metrics.authTotal)}
        onClick={metrics.authTotal > 0 ? onCheckAllStatus : undefined}
        muted={metrics.authTotal === 0}
      />
      <Tile
        icon={<Send className="h-4 w-4" />}
        label="最近发布"
        value={
          metrics.lastTask ? (
            <span className="inline-block max-w-full truncate align-middle">
              {platformLabel(metrics.lastTask.platform) ||
                metrics.lastTask.action ||
                '—'}
            </span>
          ) : metrics.taskCount > 0 ? (
            <span className="text-muted-foreground/60 text-[18px]">—</span>
          ) : (
            <span className="text-muted-foreground/60 text-[18px]">暂无</span>
          )
        }
        hint={
          metrics.lastTask
            ? `${metrics.lastTask.account ?? '—'} · ${timeAgo(metrics.lastTask.created)}`
            : metrics.taskCount > 0
              ? '查看上方任务记录'
              : '去发布中心提交一个任务吧'
        }
        accent={lastStatus.tone}
        onClick={
          metrics.lastTask
            ? onOpenTasks
            : metrics.taskCount > 0
              ? onOpenTasks
              : onOpenPublish
        }
        footer={lastTileContent}
      />
      <Tile
        icon={
          <Loader2
            className={cn(
              'h-4 w-4',
              metrics.inFlightCount > 0 && 'animate-spin',
            )}
          />
        }
        label="正在运行"
        value={metrics.inFlightCount}
        hint={
          metrics.inFlightCount > 0
            ? `${metrics.inFlightCount} 个任务进行中`
            : metrics.taskCount > 0
              ? '当前没有运行中的任务'
              : '尚无历史任务'
        }
        accent={metrics.inFlightCount > 0 ? 'warning' : null}
        onClick={metrics.taskCount > 0 ? onOpenTasks : undefined}
        muted={metrics.inFlightCount === 0}
      />
    </div>
  )
}

