import { cn } from '@/lib/utils'
import { toneTextClass } from '@/lib/tone'

/**
 * Create-group modal. Owns a small piece of UI-local state (`touched`) so
 * the validation hint doesn't pop on first render.
 */
export function CreateGroupDialog() {
  const state = useAccountsState()
  const dispatch = useAccountsDispatch()

  const [touched, setTouched] = useState(false)
  useEffect(() => {
    if (state.createDialogOpen) setTouched(false)
  }, [state.createDialogOpen])

  const validation = validateGroupName(state.newGroupName)
  const showHint = touched && !validation.ok

  const attemptSubmit = () => {
    setTouched(true)
    void dispatch.handleCreateGroup()
  }

  return (
    <Dialog open={state.createDialogOpen} onOpenChange={dispatch.setCreateDialogOpen}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>新建账号分组</DialogTitle>
          <DialogDescription>
            创建一个分组来管理多个平台的授权
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="create-name-input">分组名称</Label>
            <Input
              id="create-name-input"
              placeholder="例如：工作号、个人号、主账号"
              value={state.newGroupName}
              onChange={(e) => dispatch.setNewGroupName(e.target.value)}
              onBlur={() => setTouched(true)}
              aria-invalid={showHint}
              aria-describedby={showHint ? 'create-name-hint' : undefined}
              onKeyDown={(e) => {
                if (e.key === 'Enter') attemptSubmit()
              }}
            />
            {showHint && (
              // Inline validation hint — same Tone vocabulary as
              // GroupRenameDialog: error foreground, kept at `text-xs`.
              <p
                id="create-name-hint"
                className={cn('text-xs', toneTextClass('error'))}
              >
                {validation.message}
              </p>
            )}
          </div>
        </div>
        <DialogFooter>
          <Button
            variant="outline"
            onClick={() => dispatch.setCreateDialogOpen(false)}
          >
            取消
          </Button>
          <Button
            onClick={attemptSubmit}
            disabled={state.isCreatePending}
          >
            {state.isCreatePending && (
              <Loader2 className="h-4 w-4 mr-1 animate-spin" />
            )}
            创建
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

import { useCallback } from 'react'
import { LoginProgressModal } from '@/Components/LoginProgressModal'
import { useAccountsDispatch, useAccountsState } from '../AccountsProvider'
import { AuthorizeDialog } from './AuthorizeDialog'
import { BatchDeleteDialog } from './BatchDeleteDialog'
import { CreateGroupDialog } from './CreateGroupDialog'
import { GroupRenameDialog } from './GroupRenameDialog'

/**
 * Single mount point for every dialog used by the accounts feature. Keeps
 * AccountsPage a slim shell — it just renders <DialogHost /> once, and the
 * DialogHost renders all 5 modals (4 owned here + LoginProgressModal).
 *
 * The Login progress modal is conditionally rendered only when a group
 * has been picked (its props require a non-null groupId).
 */
export function DialogHost() {
  const state = useAccountsState()
  const dispatch = useAccountsDispatch()

  const loginModalGroupName =
    state.groups.find((g) => g.id === state.selectedGroupId)?.name ?? ''
  const loginModalPlatformLabel = dispatch.getPlatformLabel(state.selectedPlatform)

  // Stable refetch handler — prevents LoginProgressModal useEffect deps
  // from churning when DialogHost re-renders.
  const handleComplete = useCallback(() => state.refetch(), [state.refetch])

  return (
    <>
      <BatchDeleteDialog />
      <CreateGroupDialog />
      <AuthorizeDialog />
      <GroupRenameDialog />
      {state.selectedGroupId !== null && (
        <LoginProgressModal
          open={state.loginModalOpen}
          onOpenChange={dispatch.setLoginModalOpen}
          groupId={state.selectedGroupId}
          platform={state.selectedPlatform}
          groupName={loginModalGroupName}
          platformLabel={loginModalPlatformLabel}
          onComplete={handleComplete}
        />
      )}
    </>
  )
}

import { useEffect, useState } from 'react'
import { Button } from '@/Components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/Components/ui/dialog'
import { Input } from '@/Components/ui/input'
import { Label } from '@/Components/ui/label'
import { Loader2 } from 'lucide-react'
import { useAccountsDispatch, useAccountsState, validateGroupName } from '../AccountsProvider'
import { cn } from '@/lib/utils'
import { toneTextClass } from '@/lib/tone'

/**
 * Rename-group modal. Local `newName` state intentionally lived here so
 * that typing in the rename field doesn't re-render the entire accounts
 * page on every keystroke. We resync from `currentName` whenever the
 * dialog is reopened (or the source-of-truth name changes).
 */
export function GroupRenameDialog() {
  const state = useAccountsState()
  const dispatch = useAccountsDispatch()

  const [newName, setNewName] = useState(state.renameDialogCurrentName)
  useEffect(() => {
    if (state.renameDialogOpen) setNewName(state.renameDialogCurrentName)
  }, [state.renameDialogOpen, state.renameDialogCurrentName])

  const validation = validateGroupName(newName)
  const canConfirm =
    validation.ok &&
    validation.cleaned !== state.renameDialogCurrentName &&
    !state.isRenamePending

  return (
    <Dialog open={state.renameDialogOpen} onOpenChange={dispatch.setRenameDialogOpen}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>重命名分组</DialogTitle>
          <DialogDescription>
            原名称：{state.renameDialogCurrentName}
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-2">
          <Label>新名称</Label>
          <Input
            placeholder="例如：主账号、工作号"
            value={newName}
            onChange={(e) => setNewName(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && canConfirm)
                void dispatch.handleRename(state.renameDialogGroupId ?? -1, newName)
            }}
            autoFocus
          />
          {!validation.ok && newName.length > 0 && (
            // Inline validation hint — routed through `@/lib/tone` so the
            // error text color matches the rest of the form-validation
            // surface (CreateGroupDialog, TagInput at-limit state).
            <p className={cn('text-xs', toneTextClass('error'))}>{validation.message}</p>
          )}
          {validation.ok && validation.cleaned === state.renameDialogCurrentName && (
            <p className="text-xs text-muted-foreground">新名称与当前名称一致</p>
          )}
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => dispatch.setRenameDialogOpen(false)}>
            取消
          </Button>
          <Button
            disabled={!canConfirm}
            onClick={() =>
              void dispatch.handleRename(state.renameDialogGroupId ?? -1, newName)
            }
          >
            {state.isRenamePending && (
              <Loader2 className="h-4 w-4 mr-1 animate-spin" />
            )}
            确认重命名
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

import { describe, expect, it, vi } from 'vitest'
