                    </div>
                    <TagInput
                      placeholder="按 Enter 添加标签（# 可省略）"
                      value={tags}
                      onChange={(val) => setTags(val)}
                      maxTags={effectiveMaxTags([...activePlatforms])}
                    />
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
