        {/* ── 提交按钮 ─────────────────────────────────────────── */}
        <div className="flex justify-end gap-2 pt-2">
          <Button variant="outline" onClick={handleClearClick}>
            清空
          </Button>
          <Button
            onClick={submit}
            disabled={submitting}
            className="btn-elegant"
          >
            {submitting && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
            提交视频
          </Button>
        </div>

        {/* ── PR-OPT-2D: 草稿恢复条 ──── */}
        <PublishDraftBanner
          visible={pendingDraft !== null}
          savedAt={draftSavedAt}
          fieldsHint={draftBannerFieldsHint}
          fieldCount={draftFieldCountForBanner}
          onRestore={restoreDraft}
          onDiscard={discardDraft}
        />

        {/* ── PR-OPT-2D: 清空二次确认对话框 ──── */}
        <AlertDialog open={confirmClearOpen} onOpenChange={setConfirmClearOpen}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>确认清空表单？</AlertDialogTitle>
              <AlertDialogDescription>
                当前已填写 {filledFieldCount} 项字段。清空后会同时删除本地草稿，操作不可撤销。
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>取消</AlertDialogCancel>
              <AlertDialogAction
                onClick={() => {
                  setConfirmClearOpen(false)
                  clearEverything()
                }}
              >
                清空
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </>
    )
  }),
)

